#!/usr/bin/env bash

FEATURE_TO_TEST="${1}"

npx devcontainer features test \
  --project-folder features \
  --features "${FEATURE_TO_TEST}" \
  --skip-scenarios \
  --skip-duplicated \
  --base-image mcr.microsoft.com/devcontainers/base:ubuntu26.04

npx devcontainer features test \
  --project-folder features \
  --features "${FEATURE_TO_TEST}" \
  --skip-autogenerated \
  --skip-duplicated \
  --base-image mcr.microsoft.com/devcontainers/base:ubuntu26.04
